import sys, random; sys.path.insert(0,'.')
from boltons.setutils import IndexedSet
from boltons.listutils import BarrelList
bad=[]
for seed in range(400):
    r=random.Random(seed); n=r.randint(0,30); vals=list(range(n))
    s=IndexedSet(vals); ref=list(vals)
    for _ in range(r.randint(0,10)):
        if ref and r.random()<.6:
            v=r.choice(ref); s.remove(v); ref.remove(v)
        else:
            v=r.randint(100,200)
            if v not in ref: s.add(v); ref.append(v)
    for _ in range(20):
        a,b=r.choice([None,*range(-35,35)]),r.choice([None,*range(-35,35)]); st=r.choice([None,1,2,3,-1,-2])
        try: got=list(s[a:b:st])
        except Exception as e: got=repr(e)
        exp=ref[a:b:st] if not st or st>0 else None
        if exp is not None and got!=exp: bad.append(('IS slice',seed,a,b,st,got,exp)); break
        i=r.randint(-35,35)
        try: g=s[i]
        except IndexError: g='IE'
        try: e=ref[i]
        except IndexError: e='IE'
        if g!=e: bad.append(('IS idx',seed,i,g,e)); break
        try: g=s.index(ref[i]) if e!='IE' else None
        except Exception as ex: g=repr(ex)
        if e!='IE' and g!=ref.index(e): bad.append(('IS index()',seed,i,g)); break
    # BarrelList
    b=BarrelList(); b._size_factor=r.choice([2,4,8]) if hasattr(b,'_size_factor') else None
    b=BarrelList(); L=[]
    for _ in range(r.randint(0,3000)):
        op=r.random()
        if op<.5: i=r.randint(-len(L)-5,len(L)+5); x=r.random(); b.insert(i,x); L.insert(i,x)
        elif op<.6 and L: i=r.randint(-len(L),len(L)-1); assert b.pop(i)==L.pop(i)
        elif op<.62: b.sort(); L.sort()
        elif op<.64 and L: i=r.randint(-len(L),len(L)-1); j=r.randint(-len(L),len(L)); del b[i:j]; del L[i:j]
    if list(b)!=L or len(b)!=len(L): bad.append(('BL',seed,len(b),len(L)))
    if L:
      for _ in range(5):
        i=r.randint(-len(L),len(L)-1)
        if b[i]!=L[i]: bad.append(('BL idx',seed,i)); break
print(len(bad)); [print(x) for x in bad[:10]]
